const generateSystemPrompt = (user: UserProfile | undefined, memory: string, rules: string, agents: AgentProfile[]) => {
    const userName = user?.name.split(' ')[0] || 'يا ريس';

    // --- THE MAESTRO SOUL (SINGLE BLOCK FLOW) ---
    const coreIdentity = `
    **أنت "الظل" (المايسترو).**
    لسانك مصري قح، ذكي، واثق، وعميق.
    أنت لا تلقي محاضرات. أنت تعطي "الخلاصة".

    **التعليمات الذهبية (Zero Headers - Zero Hallucination):**
    1. **انسى العناوين:** إياك أن تقسم ردك بعناوين مثل (الجانب الديني - الجانب النفسي - الجانب القانوني). هذا ممنوع. تحدث كإنسان حكيم يمزج كل هذه الجوانب في فقرة أو فقرتين متماسكتين.

    2. **البناء الدرامي للرد:**
       - ابدأ بطمأنة أو احتواء (نفسي/ديني).
       - ادخل في "صلب الموضوع" بالمعلومة الدقيقة أو القانونية.
       - اختم بالتوجيه العملي (ماذا نفعل الآن).
       - كل هذا في "سرد متصل" (Flow).

    3. **الحقيقة المطلقة (البحث الإجباري):**
       - أي سؤال عن (أخبار، أسعار، طقس، مباريات، أحداث جارية) = **يجب تفعيل أداة البحث (Google Search)** فوراً.
       - لا تفتي في الأرقام أو الأخبار. إذا لم تعمل أداة البحث التلقائية، استخدم أداة 'web_search' يدوياً.
       - هات المصدر دائماً في الأخبار.

    4. **التنفيذ:**
       - اخلق أزراراً (App Buttons) لأي إجراء. لا تقل "ابحث عن كذا"، بل اصنع زر "بحث".

    **مثال للرد المرفوض (لا تفعل هذا):**
    "الجانب الديني: اصبر. الجانب القانوني: ارفع قضية." -> (هذا أسلوب آلات فاشل).

    **مثال للرد المطلوب (المايسترو):**
    "يا ريس، اللي بتمر بيه ده اختبار لليقين، وربنا مبيجبش حاجة وحشة، بس عشان نضمن حقك ومحدش يستغلك، القانون في المادة دي بيقول إن ليك تعويض كامل. أنا رأيي نهدى، ونبدأ إجراءات المحضر فوراً عشان نثبت الحالة، وأنا جهزتلك زرار الاتصال بالمحامي وزرار تاني لفتح موقع الوزارة."
    `;

    const contextData = `
    **الذاكرة الحية:** ${memory}
    **القوانين العامة:** ${rules}
    `;

    const parts: any[] = [{ text: `${coreIdentity}\n\n${contextData}` }];

    agents.forEach(a => {
        if (a.documents?.length) {
            parts.push({ text: `\n[ملف خبرة للعميل ${a.role}]:` });
            a.documents.forEach(d => parts.push({ inlineData: { mimeType: d.mimeType, data: d.data.split(',')[1] || d.data } }));
        }
    });
    return parts;
};

// --- RETRY LOGIC HELPER ---
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const generateWithRetry = async (modelName: string, params: any, maxRetries = 3, initialDelay = 1500): Promise<GenerateContentResponse> => {
    let currentDelay = initialDelay;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
            return await ai.models.generateContent({
                ...params,
                model: modelName
            });
        } catch (error: any) {
            // Retry on 503 (Overloaded) or 429 (Rate Limit)
            const isTransientError = error.message?.includes('503') || error.status === 503 || error.message?.includes('429') || error.status === 429;

            if (isTransientError && attempt < maxRetries) {
                console.warn(`[Shadow Core] Model ${modelName} overloaded/limited. Retrying in ${currentDelay}ms... (Attempt ${attempt + 1}/${maxRetries})`);
                await wait(currentDelay);
                currentDelay *= 2; // Exponential backoff
                continue;
            }
            throw error; // Throw if not transient or max retries reached
        }
    }
    throw new Error(`Failed to generate content with model ${modelName} after ${maxRetries} retries.`);
};

// --- SMART EXECUTION ENGINE ---
const executeSmartRequest = async (params: any, userHistory: any[], userMessage: string): Promise<GenerateContentResponse> => {
    // ATTEMPT 1: gemini-2.0-flash-exp (Primary - Best for Search)
    try {
        console.log("[Shadow Core] Attempting Primary Model (2.0-flash-exp)...");
        return await generateWithRetry("gemini-2.0-flash-exp", {
            ...params,
            config: { 
                ...params.config,
                // Ensure Search is ALWAYS enabled for primary model
                tools: [{ functionDeclarations: actionTools }, { googleSearch: {} }], 
                temperature: 0.5 // Lower temperature for more accurate news
            }
        }, 2); // 2 Retries
    } catch (error: any) {
        console.warn("[Shadow Core] Primary Model Failed. Switching to Fallback (3-flash-preview)...", error.message);

        // ATTEMPT 2: gemini-3-flash-preview (Fallback)
        try {
            await wait(1000); // Small cooldown before fallback
            return await generateWithRetry("gemini-3-flash-preview", {
                ...params,
                config: {
                    ...params.config,
                    // Note: 3-flash currently struggles with mixed native search + functions in some regions.
                    // We rely on the system prompt to use 'web_search' tool if it needs info.
                    tools: [{ functionDeclarations: actionTools }], 
                    temperature: 0.7,
                }
            }, 2);
        } catch (fallbackError: any) {
            console.warn("[Shadow Core] Fallback Failed. Switching to Ultimate Fallback (3-pro-preview)...");

            // ATTEMPT 3: gemini-3-pro-preview (Ultimate Fallback - Heavy Duty)
            // Pro models handle search better than flash
            return await ai.models.generateContent({
                ...params,
                model: "gemini-3-pro-preview",
                config: {
                    ...params.config,
                    tools: [{ functionDeclarations: actionTools }, { googleSearch: {} }], // Enable search for Pro fallback
                    temperature: 0.7
                }
            });
        }
    }
};

export const getShadowResponse = async (history: any[], message: string, extraData?: any, userProfile?: UserProfile, signal?: AbortSignal) => {
    if (isRequesting) return { text: "لحظة واحدة...", isError: true };
    isRequesting = true;
    try {
        const [mem, rules, agents] = await Promise.all([
            shadowDB.getMemory(userProfile?.email || 'GUEST'), 
            shadowDB.getGlobalRules(), 
            shadowDB.getAllAgents()
        ]);

        const systemParts = generateSystemPrompt(userProfile, mem.map(f => f.fact).join(" | "), rules, agents);
        const userParts: any[] = [{ text: message }];
        if (extraData?.data) userParts.push({ inlineData: { data: extraData.data, mimeType: extraData.mimeType } });

        const baseParams = {
            contents: [...history.slice(-10).map(h => ({ role: h.role, parts: [{ text: h.text }] })), { role: 'user', parts: userParts }],
            config: { systemInstruction: { parts: systemParts } },
        };

        const response = await executeSmartRequest(baseParams, history, message);

        const toolActions = response.functionCalls || []; 
        const grounding = response.candidates?.[0]?.groundingMetadata;

        const groundingLinks = grounding?.groundingChunks?.map((c: any) => ({
            title: c.web?.title || "مصدر",
            uri: c.web?.uri
        })).filter((l: any) => l.uri) || [];

        return { 
            text: response.text || "", 
            toolActions: toolActions,
            groundingLinks: groundingLinks,
            isError: false
        };
    } catch (e: any) {
        console.error("Gemini Critical Error:", e);
        let errorMsg = "الشبكة فيها مشكلة بسيطة، جرب تاني.";
        if (e.message?.includes('429')) errorMsg = "ضغط عالي جداً على الشبكة العصبية. ثواني وراجعلك.";
        if (e.message?.includes('503')) errorMsg = "السيرفرات مشغولة جداً (Global Overload). بحاول أعمل اتصال بديل.. جرب كمان دقيقة.";
        return { text: errorMsg, isError: true };
    } finally { isRequesting = false; }
};

export const playShadowVoice = async (text: string, voice: string, existing?: string, onEnded?: () => void) => {
    stopVoice();
    const ctx = resumeAudioContext();
    if (!ctx) { 
        // Audio Context Failed - Fallback to Native TTS immediately
        fallbackNativeTTS(text, onEnded);
        return; 
    }

    try {
        let base64 = existing;
        if (!base64 && audioCache.has(text)) base64 = audioCache.get(text);
        else if (!base64) {
            base64 = await getShadowVoice(text, voice);
            if (base64) audioCache.set(text, base64);
        }

        if (!base64) { 
            // API TTS Failed - Fallback to Native TTS
            fallbackNativeTTS(text, onEnded);
            return; 
        }

        const buffer = await decodeAudioData(decode(base64), ctx);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => { currentSource = null; onEnded?.(); };
        source.start(0);
        currentSource = source;
    } catch (e) { 
        console.error("Voice Playback Error:", e); 
        fallbackNativeTTS(text, onEnded);
    }
};

// Fallback System for Alarms
const fallbackNativeTTS = (text: string, onEnded?: () => void) => {
    try {
        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'ar-EG';
        utterance.rate = 1.0;
        utterance.onend = () => onEnded?.();
        window.speechSynthesis.speak(utterance);
    } catch(e) {
        onEnded?.();
    }
};

export const getShadowVoice = async (text: string, voice: string) => {
    try {
        const res = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text }] }],
            config: { 
                responseModalities: [Modality.AUDIO], 
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice === 'female' ? 'Kore' : 'Fenrir' } } } 
            }
        });
        return res.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
    } catch (e) { return null; }
};

export const stopVoice = () => { 
    if (currentSource) { try { currentSource.stop(); } catch {} currentSource = null; } 
    if (window.speechSynthesis) window.speechSynthesis.cancel();
};

function decode(b: string) { const s = atob(b); const u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u; }
async function decodeAudioData(d: Uint8Array, c: AudioContext) { const i16 = new Int16Array(d.buffer); const b = c.createBuffer(1, i16.length, 24000); const cd = b.getChannelData(0); for (let i = 0; i < i16.length; i++) cd[i] = i16[i] / 32768.0; return b; }

import React, { useState, useEffect } from 'react';
import ChatInterface from './components/ChatInterface';
import Pricing from './components/Pricing';
import Auth from './components/Auth';
import Payment from './components/Payment';
import AdminDashboard from './components/AdminDashboard';
import SecurityGate from './components/SecurityGate';
import AffiliateDashboard from './components/AffiliateDashboard';
import Dashboard from './components/Dashboard'; 
import LiveTickers from './components/LiveTickers'; 
import InstallPrompt from './components/InstallPrompt';
import { shadowDB, UserProfile, DBMessage } from './services/dbService';
import { playShadowVoice, stopVoice } from './services/geminiService';
import { Loader2, Fingerprint, ShieldCheck, Clock, CheckCircle2, Home, LogOut, RefreshCw } from 'lucide-react';

type ViewState = 'loading' | 'pricing' | 'auth' | 'payment' | 'dashboard' | 'chat' | 'admin' | 'blocked' | 'pending_review' | 'affiliate';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('loading');
  const [user, setUser] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<string>('elite');
  const [billingCycle, setBillingCycle] = useState<'monthly' | 'yearly'>('monthly'); 
  const [authDefaultTab, setAuthDefaultTab] = useState<'login' | 'register'>('login');
  const [isAffiliateRegistration, setIsAffiliateRegistration] = useState(false);
  const [isCheckingStatus, setIsCheckingStatus] = useState(false);

  const [dashboardAction, setDashboardAction] = useState<string | null>(null);
  const [isAppLocked, setIsAppLocked] = useState(true);
  const [latestSystemMessage, setLatestSystemMessage] = useState<DBMessage | null>(null);

  // --- POKA-YOKE NAVIGATION HANDLER ---
  useEffect(() => {
      if (view === 'chat' || view === 'affiliate') {
          window.history.pushState({ view }, '');
      }

      const handlePopState = (event: PopStateEvent) => {
          if (view === 'chat' || view === 'affiliate') {
              setView('dashboard'); 
          } 
      };

      window.addEventListener('popstate', handlePopState);
      return () => window.removeEventListener('popstate', handlePopState);
  }, [view]);

  useEffect(() => {
    checkSession();
  }, []);

  // --- GLOBAL SYSTEM SYNC (Pulse, Rules, Agents) ---
  useEffect(() => {
      if (!user) return;

      // Subscribe to Global System Changes
      shadowDB.subscribeToSystem(
          (pulse) => {
              if (pulse) {
                  const lastSeen = user.lastPulseReceived || 0;
                  if (pulse.timestamp > lastSeen + 1000) {
                      const pulseMsg: DBMessage = {
                          userId: user.email,
                          role: 'system',
                          text: `📢 **نداء عام (Shadow Pulse):**\n\n${pulse.text}`,
                          timestamp: pulse.timestamp
                      };
                      shadowDB.saveMessage(pulseMsg).then(() => {
                          setLatestSystemMessage(pulseMsg);
                          shadowDB.updateLastPulseReceived(user.email, pulse.timestamp);
                          setUser(prev => prev ? ({ ...prev, lastPulseReceived: pulse.timestamp }) : null);
                          const audio = document.getElementById('notification-sound') as HTMLAudioElement;
                          if (audio) { audio.volume = 1.0; audio.play().catch(e => {}); }
                      });
                  }
              }
          },
          (rules) => {
              // Rules updated silently in background via dbService
              console.log("[System] Global rules updated.");
          }
      );

      // Existing User-Specific Task Checks (ALARMS)
      const runBackgroundChecks = async () => {
        if (isAppLocked) return;
        const now = Date.now();
        const allTasks = await shadowDB.getTasks(user.email);

        // Find tasks due (with a 1-minute buffer to catch tasks that just passed)
        const dueTasks = allTasks.filter(t => 
            t.status === 'pending' && 
            !t.notified && 
            t.executionTime && 
            t.executionTime <= now
        );

        if (dueTasks.length > 0) {
            const task = dueTasks[0];
            const reminderText = `🔔 تنبيه: ميعاد "${task.task}" جه يا ريس.`;

            // 1. Play Digital Beep Immediate
            const audio = document.getElementById('notification-sound') as HTMLAudioElement;
            if (audio) { 
                audio.volume = 1.0; 
                try {
                     // Force promise handling
                     await audio.play();
                } catch(e) { console.log("Audio play blocked by browser", e); }
            }

            // 2. Play Voice (With Robust Fallback inside geminiService)
            setTimeout(() => { 
                playShadowVoice(reminderText, user.voicePreference || 'male'); 
            }, 1000);

            // 3. Save Message to Chat
            const alarmMsg: DBMessage = {
                userId: user.email,
                role: 'system',
                text: reminderText,
                timestamp: Date.now()
            };
            await shadowDB.saveMessage(alarmMsg);
            setLatestSystemMessage(alarmMsg);

            // 4. Mark Done
            await shadowDB.updateTaskStatus(task.id!, { notified: true });
        }
      };

      // Increased frequency to 5 seconds (5000ms) for better precision
      const interval = setInterval(runBackgroundChecks, 5000);
      return () => { clearInterval(interval); stopVoice(); };
  }, [user?.email, isAppLocked]); // Re-run if user email changes

  // --- ADMIN NOTIFIER ---
  useEffect(() => {
      if (user && (user.email === 'TITO' || user.email === 'tito@shadow.com')) {
          const interval = setInterval(async () => {
            const lastCheck = await shadowDB.getConfig('last_admin_check') || 0; 
            const allProfiles = await shadowDB.getAllProfiles();
            const newPending = allProfiles.filter(p => p.status === 'pending' && p.paymentProof && p.joinedAt > lastCheck);
            const allFeedback = await shadowDB.getAllFeedback();
            const newFeedback = allFeedback.filter(f => f.timestamp > lastCheck);

            if (newPending.length > 0 || newFeedback.length > 0) {
                let msgText = "🔴 **تقرير عمليات (New Alert)**:\n";
                if (newPending.length > 0) msgText += `\n📌 **طلبات اشتراك جديدة (${newPending.length})**`;
                if (newFeedback.length > 0) msgText += `\n💬 **رسائل رأي جديدة (${newFeedback.length})**`;

                const adminMsg: DBMessage = { userId: 'TITO', role: 'system', text: msgText, timestamp: Date.now() };
                await shadowDB.saveMessage(adminMsg);
                setLatestSystemMessage(adminMsg);
                await shadowDB.setConfig('last_admin_check', Date.now());
                const audio = document.getElementById('notification-sound') as HTMLAudioElement;
                if (audio) { audio.play().catch(e => {}); }
            }
          }, 60000);
          return () => clearInterval(interval);
      }
  }, [user]);

  useEffect(() => {
    let interval: any;
    if (view === 'pending_review' && user && user.tier === 'sovereign') {
        interval = setInterval(async () => {
            checkStatusManual();
        }, 5000); 
    }
    return () => clearInterval(interval);
  }, [view, user]);

  const checkStatusManual = async () => {
      if (!user) return;
      setIsCheckingStatus(true);
      const updatedProfile = await shadowDB.getProfile(user.email);
      if (updatedProfile && updatedProfile.status === 'active') {
          setUser(updatedProfile);
          setView('dashboard'); 
      }
      setTimeout(() => setIsCheckingStatus(false), 1000);
  };

  const checkSession = async () => {
    try {
      const lastUserEmail = localStorage.getItem('shadow_last_user');
      const guestSession = localStorage.getItem('shadow_guest_active');

      if (lastUserEmail && lastUserEmail !== 'GUEST') {
          // Attempt rapid restore using local DB
          const profile = await shadowDB.getProfile(lastUserEmail);

          if (profile) {
              setUser(profile);
              if (profile.status === 'active') {
                 if (profile.email === 'TITO' || profile.email === 'tito@shadow.com') {
                     setView('admin');
                     setIsAppLocked(false);
                 } else {
                     setView('dashboard');
                     setIsAppLocked(true); 
                 }
                 return;
              } else if (profile.status === 'pending') {
                 if (profile.paymentProof) {
                     setView('pending_review');
                 } else {
                     setView('payment');
                 }
                 return;
              }
          }
      }

      if (guestSession === 'true') {
        const guestUser: UserProfile = { email: 'GUEST', name: 'ضيف', tier: 'lite', status: 'active', joinedAt: Date.now() };
        setUser(guestUser);
        setView('dashboard');
        setIsAppLocked(true); 
        return;
      }

      setView('pricing');
    } catch (e) {
      setView('pricing');
    }
  };

  const handleAuthSuccess = async (profile: UserProfile) => {
    setUser(profile);
    localStorage.setItem('shadow_last_user', profile.email);
    setLatestSystemMessage(null);

    // Guest Migration (Basic)
    if (localStorage.getItem('shadow_guest_history')) {
        localStorage.removeItem('shadow_guest_history');
        localStorage.removeItem('shadow_guest_active');
    }

    if (profile.email === 'TITO' || profile.email === 'tito@shadow.com' || (profile.tier === 'sovereign' && profile.name.includes('تيتو'))) {
        setView('admin');
        setIsAppLocked(false); 
        return;
    }

    if (profile.tier === 'lite' && profile.affiliate?.isMarketer) {
         setView('dashboard');
         setIsAppLocked(false);
         return;
    }

    if (profile.status === 'active') {
        setView('dashboard'); 
        setIsAppLocked(false); 
    } else if (profile.status === 'pending') {
        if (profile.paymentProof) setView('pending_review');
        else setView('payment');
    } else {
        setView('blocked');
    }
  };

  const handleGuestAccess = () => {
      localStorage.setItem('shadow_guest_active', 'true');
      if (!localStorage.getItem('shadow_guest_start')) {
          localStorage.setItem('shadow_guest_start', Date.now().toString());
      }
