import React, { useState, useEffect } from 'react';
import ChatInterface from './components/ChatInterface';
import Pricing from './components/Pricing';
import Auth from './components/Auth';
import Payment from './components/Payment';
import AdminDashboard from './components/AdminDashboard';
import SecurityGate from './components/SecurityGate';
import AffiliateDashboard from './components/AffiliateDashboard';
import Dashboard from './components/Dashboard'; 
import LiveTickers from './components/LiveTickers'; 
import InstallPrompt from './components/InstallPrompt';
import { shadowDB, UserProfile, DBMessage } from './services/dbService';
import { playShadowVoice, stopVoice, resumeAudioContext } from './services/geminiService';
import { Loader2, Fingerprint, ShieldCheck, Clock, CheckCircle2, Home, LogOut, RefreshCw } from 'lucide-react';

type ViewState = 'loading' | 'pricing' | 'auth' | 'payment' | 'dashboard' | 'chat' | 'admin' | 'blocked' | 'pending_review' | 'affiliate';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('loading');
  const [user, setUser] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<string>('elite');
  const [billingCycle, setBillingCycle] = useState<'monthly' | 'yearly'>('monthly'); 
  const [authDefaultTab, setAuthDefaultTab] = useState<'login' | 'register'>('login');
  const [isAffiliateRegistration, setIsAffiliateRegistration] = useState(false);
  const [isCheckingStatus, setIsCheckingStatus] = useState(false);

  const [dashboardAction, setDashboardAction] = useState<string | null>(null);
  const [isAppLocked, setIsAppLocked] = useState(true);
  const [latestSystemMessage, setLatestSystemMessage] = useState<DBMessage | null>(null);

  // --- POKA-YOKE NAVIGATION HANDLER ---
  useEffect(() => {
      if (view === 'chat' || view === 'affiliate') {
          window.history.pushState({ view }, '');
      }

      const handlePopState = (event: PopStateEvent) => {
          if (view === 'chat' || view === 'affiliate') {
              setView('dashboard'); 
          } 
      };

      window.addEventListener('popstate', handlePopState);
      return () => window.removeEventListener('popstate', handlePopState);
  }, [view]);

  useEffect(() => {
    checkSession();
  }, []);

  // --- GLOBAL SYSTEM SYNC (Pulse, Rules, Agents) ---
  useEffect(() => {
      if (!user) return;

      // Subscribe to Global System Changes
      shadowDB.subscribeToSystem(
          (pulse) => {
              if (pulse) {
                  const lastSeen = user.lastPulseReceived || 0;
                  if (pulse.timestamp > lastSeen + 1000) {
                      const pulseMsg: DBMessage = {
                          userId: user.email,
                          role: 'system',
                          text: `📢 **نداء عام (Shadow Pulse):**\n\n${pulse.text}`,
                          timestamp: pulse.timestamp
                      };
                      shadowDB.saveMessage(pulseMsg).then(() => {
                          setLatestSystemMessage(pulseMsg);
                          shadowDB.updateLastPulseReceived(user.email, pulse.timestamp);
                          setUser(prev => prev ? ({ ...prev, lastPulseReceived: pulse.timestamp }) : null);
                          const audio = document.getElementById('notification-sound') as HTMLAudioElement;
                          if (audio) { audio.volume = 1.0; audio.play().catch(e => {}); }
                      });
                  }
              }
          },
          (rules) => {
              // Rules updated silently in background via dbService
              console.log("[System] Global rules updated.");
          }
      );

      // Existing User-Specific Task Checks (ALARMS)
      const runBackgroundChecks = async () => {
        if (isAppLocked) return;
        const now = Date.now();
        const allTasks = await shadowDB.getTasks(user.email);

        // Find tasks due (Looking back 2 minutes to catch any missed in small interval gaps)
        const dueTasks = allTasks.filter(t => 
            t.status === 'pending' && 
            !t.notified && 
            t.executionTime && 
            t.executionTime <= now
        );

        if (dueTasks.length > 0) {
            const task = dueTasks[0];
            const reminderText = `🔔 تنبيه: ميعاد "${task.task}" جه يا ريس.`;

            console.log("ALARM TRIGGERED:", task.task);

            // 0. Wake up Audio Context if possible
            resumeAudioContext();

            // 1. Play Digital Beep (Aggressive Try)
            const audio = document.getElementById('notification-sound') as HTMLAudioElement;
            if (audio) { 
                audio.volume = 1.0; 
                audio.currentTime = 0;
                audio.play().catch(error => {
                    console.warn("Auto-play prevented (User didn't interact yet).");
                });
            }

            // 2. Play Voice using NATIVE TTS (Much faster and reliable for alarms)
            setTimeout(() => { 
               if ('speechSynthesis' in window) {
                   const utterance = new SpeechSynthesisUtterance(reminderText);
                   utterance.lang = 'ar-EG';
                   utterance.rate = 1.0;
                   window.speechSynthesis.speak(utterance);
               } else {
                   // Fallback to Gemini Voice if native fails
                   playShadowVoice(reminderText, user.voicePreference || 'male'); 
               }
            }, 1000);

            // 3. Save Message to Chat
            const alarmMsg: DBMessage = {
                userId: user.email,
                role: 'system',
                text: reminderText,
                timestamp: Date.now()
            };
            await shadowDB.saveMessage(alarmMsg);
            setLatestSystemMessage(alarmMsg);

            // 4. Mark Done
            await shadowDB.updateTaskStatus(task.id!, { notified: true });
        }
      };

      // Interval set to 5 seconds
      const interval = setInterval(runBackgroundChecks, 5000);
      return () => { clearInterval(interval); stopVoice(); };
  }, [user?.email, isAppLocked]); // Re-run if user email changes

  // --- ADMIN NOTIFIER ---
  useEffect(() => {
      if (user && (user.email === 'TITO' || user.email === 'tito@shadow.com')) {
          const interval = setInterval(async () => {
            const lastCheck = await shadowDB.getConfig('last_admin_check') || 0; 
            const allProfiles = await shadowDB.getAllProfiles();
            const newPending = allProfiles.filter(p => p.status === 'pending' && p.paymentProof && p.joinedAt > lastCheck);
            const allFeedback = await shadowDB.getAllFeedback();
            const newFeedback = allFeedback.filter(f => f.timestamp > lastCheck);

            if (newPending.length > 0 || newFeedback.length > 0) {
                let msgText = "🔴 **تقرير عمليات (New Alert)**:\n";
                if (newPending.length > 0) msgText += `\n📌 **طلبات اشتراك جديدة (${newPending.length})**`;
                if (newFeedback.length > 0) msgText += `\n💬 **رسائل رأي جديدة (${newFeedback.length})**`;

                const adminMsg: DBMessage = { userId: 'TITO', role: 'system', text: msgText, timestamp: Date.now() };
                await shadowDB.saveMessage(adminMsg);
                setLatestSystemMessage(adminMsg);
                await shadowDB.setConfig('last_admin_check', Date.now());
                const audio = document.getElementById('notification-sound') as HTMLAudioElement;
                if (audio) { audio.play().catch(e => {}); }
            }
          }, 60000);
          return () => clearInterval(interval);
      }
  }, [user]);

  useEffect(() => {
    let interval: any;
    if (view === 'pending_review' && user && user.tier === 'sovereign') {
        interval = setInterval(async () => {
            checkStatusManual();
        }, 5000); 
    }
    return () => clearInterval(interval);
  }, [view, user]);

  const checkStatusManual = async () => {
      if (!user) return;
      setIsCheckingStatus(true);
      const updatedProfile = await shadowDB.getProfile(user.email);
      if (updatedProfile && updatedProfile.status === 'active') {
          setUser(updatedProfile);
          setView('dashboard'); 
      }
      setTimeout(() => setIsCheckingStatus(false), 1000);
  };

  const checkSession = async () => {
    try {
      const lastUserEmail = localStorage.getItem('shadow_last_user');
      const guestSession = localStorage.getItem('shadow_guest_active');

      if (lastUserEmail && lastUserEmail !== 'GUEST') {
          // Attempt rapid restore using local DB
          const profile = await shadowDB.getProfile(lastUserEmail);

          if (profile) {
              setUser(profile);
              if (profile.status === 'active') {
                 if (profile.email === 'TITO' || profile.email === 'tito@shadow.com') {
                     setView('admin');
                     setIsAppLocked(false);
                 } else {
                     setView('dashboard');
                     setIsAppLocked(true); 
                 }
                 return;
              } else if (profile.status === 'pending') {
                 if (profile.paymentProof) {
                     setView('pending_review');
                 } else {
                     setView('payment');
                 }
                 return;
              }
          }
      }

      if (guestSession === 'true') {
        const guestUser: UserProfile = { email: 'GUEST', name: 'ضيف', tier: 'lite', status: 'active', joinedAt: Date.now() };
        setUser(guestUser);
        setView('dashboard');
        setIsAppLocked(true); 
        return;
      }

      setView('pricing');
    } catch (e) {
      setView('pricing');
    }
  };

  const handleAuthSuccess = async (profile: UserProfile) => {
    setUser(profile);
    localStorage.setItem('shadow_last_user', profile.email);
    setLatestSystemMessage(null);

    // Guest Migration (Basic)
    if (localStorage.getItem('shadow_guest_history')) {
        localStorage.removeItem('shadow_guest_history');
        localStorage.removeItem('shadow_guest_active');
    }

    if (profile.email === 'TITO' || profile.email === 'tito@shadow.com' || (profile.tier === 'sovereign' && profile.name.includes('تيتو'))) {
        setView('admin');
        setIsAppLocked(false); 
        return;
    }

    if (profile.tier === 'lite' && profile.affiliate?.isMarketer) {
         setView('dashboard');
         setIsAppLocked(false);
         return;
    }

    if (profile.status === 'active') {
        setView('dashboard'); 
        setIsAppLocked(false); 
    } else if (profile.status === 'pending') {
        if (profile.paymentProof) setView('pending_review');
        else setView('payment');
    } else {
        setView('blocked');
    }
  };

  const handleGuestAccess = () => {
      localStorage.setItem('shadow_guest_active', 'true');
      if (!localStorage.getItem('shadow_guest_start')) {
          localStorage.setItem('shadow_guest_start', Date.now().toString());
      }
      const guestUser: UserProfile = { email: 'GUEST', name: 'ضيف', tier: 'lite', status: 'active', joinedAt: Date.now() };
      setUser(guestUser);
      setLatestSystemMessage(null);
      setView('dashboard');
      setIsAppLocked(false);
  };

  const handleAdminLogin = async () => {
      let adminProfile = await shadowDB.getProfile('TITO');

      if (!adminProfile) {
          adminProfile = { 
              email: 'TITO', 
              name: 'تيتو (المالك)', 
              shadowName: 'الظل الأبدي', 
              tier: 'sovereign', 
              status: 'active', 
              joinedAt: Date.now(),
              affiliate: {
                  isMarketer: true,
