const generateSystemPrompt = (user: UserProfile | undefined, memory: string, rules: string, agents: AgentProfile[]) => {

    // --- THE MAESTRO SOUL ---
    const coreIdentity = `
    **أنت "الظل" (المايسترو).**
    أنت أقوى مساعد شخصي مصري، ذكي، حكيم، ومسيطر.

    **قواعد الرد الصارمة (System Protocol):**
    1. **ممنوع الردود الفارغة:** إذا استخدمت أداة (مثل البحث)، يجب أن تلخص النتيجة للمستخدم في رد نصي واضح.
    2. **البحث المباشر (Live Search):** أي سؤال عن (أخبار، أسعار، طقس، مباريات، أحداث جارية) = استخدم Google Search فوراً، ولخص الأخبار في نقاط سريعة مع المصادر.
    3. **الأدوات:** لا تستخدم أداة فتح التطبيقات (app_control) إلا بطلب صريح.
    4. **الشخصية:** تحدث بلهجة مصرية قوية، واثقة، ومختصرة. أنت "الريس" في مجالك.
    5. **السياق:** أنت تعرف كل شيء عن المستخدم من الذاكرة أدناه.

    **الذاكرة الحية:** ${memory}
    **القوانين العامة:** ${rules}
    `;

    const parts: any[] = [{ text: coreIdentity }];

    agents.forEach(a => {
        if (a.documents?.length) {
            parts.push({ text: `\n[ملف خبرة للعميل ${a.role}]:` });
            a.documents.forEach(d => parts.push({ inlineData: { mimeType: d.mimeType, data: d.data.split(',')[1] || d.data } }));
        }
    });
    return parts;
};

// --- RETRY LOGIC HELPER ---
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const generateWithRetry = async (modelName: string, params: any, maxRetries = 2, initialDelay = 1500): Promise<GenerateContentResponse> => {
    let currentDelay = initialDelay;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
            return await ai.models.generateContent({
                ...params,
                model: modelName
            });
        } catch (error: any) {
            const isTransientError = error.message?.includes('503') || error.status === 503 || error.message?.includes('429') || error.status === 429;
            if (isTransientError && attempt < maxRetries) {
                console.warn(`[Shadow Core] Model ${modelName} retry ${attempt+1}...`);
                await wait(currentDelay);
                currentDelay *= 2; 
                continue;
            }
            throw error; 
        }
    }
    throw new Error(`Failed to generate content with model ${modelName}.`);
};

