        } catch (flashError: any) {
             console.warn("[Shadow Core] Flash 3 Limited. Switching to Flash Lite (Safety Net)...", flashError.message);

             // ATTEMPT 3: gemini-flash-lite-latest (Ultra-light fallback)
             // CRITICAL FIX: Flash Lite DOES NOT support 'googleSearch' mixed with tools, or sometimes at all.
