const executeSmartRequest = async (params: any, userHistory: any[], userMessage: string): Promise<GenerateContentResponse> => {
    // STRATEGY: 3 Pro -> 3 Flash -> Flash Lite
    // CRITICAL: Live Search (googleSearch) MUST be enabled on ALL levels.

    const toolsConfig = [{ functionDeclarations: actionTools }, { googleSearch: {} }];

    // ATTEMPT 1: gemini-3-pro-preview (The Genius)
    try {
        return await generateWithRetry("gemini-3-pro-preview", {
            ...params,
            config: { 
                ...params.config,
                tools: toolsConfig, 
                temperature: 0.6 
            }
        }, 1, 1000); 
    } catch (error: any) {
        console.warn("[Shadow Core] Gemini 3 Pro Limit/Error. Switching to 3 Flash...", error.message);

        // ATTEMPT 2: gemini-3-flash-preview (High Speed & Efficiency - Best Alternate)
        try {
            return await generateWithRetry("gemini-3-flash-preview", {
                ...params,
                config: {
                    ...params.config,
                    tools: toolsConfig, 
                    temperature: 0.7,
                }
            }, 1, 2000);
        } catch (flashError: any) {
             console.warn("[Shadow Core] 3 Flash Limited. Switching to Flash Lite (Safety Net)...", flashError.message);

             // ATTEMPT 3: gemini-flash-lite-latest (The Ultimate Fallback)
             // Tries with SEARCH first.
             try {
                return await generateWithRetry("gemini-flash-lite-latest", {
                    ...params,
                    config: {
                        ...params.config,
                        tools: toolsConfig,
                        temperature: 0.7,
                    }
                }, 1, 2500);
             } catch (liteError: any) {
                 // If Lite fails with 400 (Tool unsupported), try ONE LAST TIME without search to avoid crash.
                 if (liteError.message?.includes('400') || liteError.status === 400) {
                     console.warn("[Shadow Core] Lite refused tools. Retrying barebone...", liteError.message);
                     return await generateWithRetry("gemini-flash-lite-latest", {
                        ...params,
                        config: {
                            ...params.config,
                            tools: [{ functionDeclarations: actionTools }], // Remove Search, keep functions
                            temperature: 0.7,
                        }
                    }, 0, 1000);
                 }
                 throw liteError;
             }
        }
    }
};

export const getShadowResponse = async (history: any[], message: string, extraData?: any, userProfile?: UserProfile, signal?: AbortSignal) => {
    if (isRequesting) return { text: "لحظة واحدة...", isError: true };
    isRequesting = true;
    try {
        const [mem, rules, agents] = await Promise.all([
            shadowDB.getMemory(userProfile?.email || 'GUEST'), 
            shadowDB.getGlobalRules(), 
            shadowDB.getAllAgents()
        ]);

        const systemParts = generateSystemPrompt(userProfile, mem.map(f => f.fact).join(" | "), rules, agents);
        const userParts: any[] = [{ text: message }];
        if (extraData?.data) userParts.push({ inlineData: { data: extraData.data, mimeType: extraData.mimeType } });

        const baseParams = {
            contents: [...history.slice(-10).map(h => ({ role: h.role, parts: [{ text: h.text }] })), { role: 'user', parts: userParts }],
            config: { systemInstruction: { parts: systemParts } },
        };

        const response = await executeSmartRequest(baseParams, history, message);

        // --- ROBUST RESPONSE PARSING ---
        const toolActions = response.functionCalls || []; 
        const grounding = response.candidates?.[0]?.groundingMetadata;

        // Extract text safely. If text is empty but we have candidates, try to find text parts manually.
        let finalText = response.text || "";
        if (!finalText && response.candidates?.[0]?.content?.parts) {
            finalText = response.candidates[0].content.parts
                .filter((p: any) => p.text)
                .map((p: any) => p.text)
                .join("\n");
        }

        const groundingLinks = grounding?.groundingChunks?.map((c: any) => ({
            title: c.web?.title || "مصدر",
            uri: c.web?.uri
        })).filter((l: any) => l.uri) || [];

        return { 
            text: finalText, 
            toolActions: toolActions,
            groundingLinks: groundingLinks,
            isError: false
        };
    } catch (e: any) {
        console.error("Gemini Critical Error:", e);
        let errorMsg = "الشبكة فيها مشكلة بسيطة، جرب تاني.";
        // More specific user messages for persistence errors
        if (e.message?.includes('429')) errorMsg = "السيرفرات مضغوطة جداً حالياً (Rate Limit). جرب كمان دقيقة.";
        if (e.message?.includes('503')) errorMsg = "خدمة الذكاء الاصطناعي مشغولة. بحاول أعمل اتصال بديل..";
        if (e.message?.includes('404')) errorMsg = "نظام الذكاء الاصطناعي بيتعمل له تحديث. ثواني وراجع.";
        // 400 with 'tool use' usually means the specific model doesn't support the tool, but we are using valid models now.
        if (e.message?.includes('400')) errorMsg = "موديل الذكاء الاصطناعي مش قادر ينفذ الأمر ده دلوقتي. جرب بصيغة تانية.";
        return { text: errorMsg, isError: true };
    } finally { isRequesting = false; }
};

export const playShadowVoice = async (text: string, voice: string, existing?: string, onEnded?: () => void) => {
    stopVoice();
    const ctx = resumeAudioContext();

    // Check if browser supports speech synthesis (Native Fallback is faster/cheaper/more reliable for alarms)
    if ('speechSynthesis' in window && !existing) {
        fallbackNativeTTS(text, onEnded);
        return;
    }

    if (!ctx) { 
        fallbackNativeTTS(text, onEnded);
        return; 
    }

    try {
        let base64 = existing;
        if (!base64 && audioCache.has(text)) base64 = audioCache.get(text);
        else if (!base64) {
            base64 = await getShadowVoice(text, voice);
            if (base64) audioCache.set(text, base64);
        }

        if (!base64) { 
            fallbackNativeTTS(text, onEnded);
            return; 
        }

        const buffer = await decodeAudioData(decode(base64), ctx);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => { currentSource = null; onEnded?.(); };
        source.start(0);
        currentSource = source;
    } catch (e) { 
        console.error("Voice Playback Error:", e); 
        fallbackNativeTTS(text, onEnded);
    }
};

const fallbackNativeTTS = (text: string, onEnded?: () => void) => {
    try {
        window.speechSynthesis.cancel();

        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'ar-EG';
        utterance.rate = 1.0; 
        utterance.pitch = 1.0;

        const voices = window.speechSynthesis.getVoices();
        const arabicVoice = voices.find(v => v.lang.includes('ar'));
        if (arabicVoice) utterance.voice = arabicVoice;

        utterance.onend = () => onEnded?.();
        utterance.onerror = (e) => { console.warn("TTS Error", e); onEnded?.(); };

        window.speechSynthesis.speak(utterance);
    } catch(e) {
        onEnded?.();
    }
};

export const getShadowVoice = async (text: string, voice: string) => {
    try {
        const res = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text }] }],
            config: { 
                responseModalities: [Modality.AUDIO], 
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice === 'female' ? 'Kore' : 'Fenrir' } } } 
            }
        });
        return res.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
    } catch (e) { return null; }
};

export const stopVoice = () => { 
    if (currentSource) { try { currentSource.stop(); } catch {} currentSource = null; } 
    if (window.speechSynthesis) window.speechSynthesis.cancel();
};

function decode(b: string) { const s = atob(b); const u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u; }
async function decodeAudioData(d: Uint8Array, c: AudioContext) { const i16 = new Int16Array(d.buffer); const b = c.createBuffer(1, i16.length, 24000); const cd = b.getChannelData(0); for (let i = 0; i < i16.length; i++) cd[i] = i16[i] / 32768.0; return b; }

