const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const generateWithRetry = async (modelName: string, params: any, maxRetries = 2, initialDelay = 2000): Promise<GenerateContentResponse> => {
    let currentDelay = initialDelay;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
            return await ai.models.generateContent({
                ...params,
                model: modelName
            });
        } catch (error: any) {
            // 429: Quota Exhausted (Rate Limit)
            // 503: Service Unavailable
            const isTransientError = error.message?.includes('503') || error.status === 503 || error.message?.includes('429') || error.status === 429;

            if (isTransientError && attempt < maxRetries) {
                console.warn(`[Shadow Core] Model ${modelName} hit limit (${error.status}). Retrying in ${currentDelay}ms... (Attempt ${attempt + 1}/${maxRetries})`);
                await wait(currentDelay);
                currentDelay *= 1.5; // Exponential Backoff
                continue;
            }
            throw error; 
        }
    }
    throw new Error(`Failed to generate content with model ${modelName}.`);
};

