        // We drop 'googleSearch' if it causes issues, but keep functions.
        try {
            return await generateWithRetry("gemini-flash-latest", {
                ...params,
                config: {
                    ...params.config,
                    tools: [{ functionDeclarations: actionTools }], // Simplified tools for backup
                    temperature: 0.7,
                }
            });
        } catch (finalError) {
             // Ultimate Fallback: gemini-flash-lite-latest (The Emergency Radio)
             return await generateWithRetry("gemini-flash-lite-latest", {
                 ...params,
                 config: { ...params.config, tools: [] } // Text only
             }, 0);
        }
    }
};

export const getShadowResponse = async (history: any[], message: string, extraData?: any, userProfile?: UserProfile, signal?: AbortSignal) => {
    if (isRequesting) return { text: "لحظة واحدة يا ريس.. بجمع المعلومات.", isError: true };
    isRequesting = true;

    try {
        const [mem, rules, agents] = await Promise.all([
            shadowDB.getMemory(userProfile?.email || 'GUEST'), 
            shadowDB.getGlobalRules(), 
            shadowDB.getAllAgents()
        ]);

        const systemParts = generateSystemPrompt(userProfile, mem.map(f => f.fact).join(" | "), rules, agents);
        const userParts: any[] = [{ text: message }];
        if (extraData?.data) userParts.push({ inlineData: { data: extraData.data, mimeType: extraData.mimeType } });

        const baseParams = {
            contents: [...history.slice(-8).map(h => ({ role: h.role, parts: [{ text: h.text }] })), { role: 'user', parts: userParts }],
            config: { systemInstruction: { parts: systemParts } },
        };

        const response = await executeSmartRequest(baseParams, history, message);

        // --- RESPONSE PROCESSING ---
        const toolActions = response.functionCalls || []; 
        const grounding = response.candidates?.[0]?.groundingMetadata;

        let finalText = response.text || "";
        if (!finalText && response.candidates?.[0]?.content?.parts) {
            finalText = response.candidates[0].content.parts
                .filter((p: any) => p.text)
                .map((p: any) => p.text)
                .join("\n");
        }

        const groundingLinks = grounding?.groundingChunks?.map((c: any) => ({
            title: c.web?.title || "مصدر",
            uri: c.web?.uri
        })).filter((l: any) => l.uri) || [];

        return { 
            text: finalText, 
            toolActions: toolActions,
            groundingLinks: groundingLinks,
            isError: false
        };

    } catch (e: any) {
        console.error("Gemini Critical:", e);
        let errorMsg = "الشبكة فيها مشكلة بسيطة، جرب تاني.";
        if (e.message?.includes('429')) errorMsg = "ضغط شغل عالي.. ثانية واحدة وراجعلك.";
        if (e.message?.includes('503')) errorMsg = "السيرفرات بتعمل صيانة لحظية.. جرب تاني.";
        return { text: errorMsg, isError: true };
    } finally { isRequesting = false; }
};

// --- VOICE ENGINE ---
export const playShadowVoice = async (text: string, voice: string, existing?: string, onEnded?: () => void) => {
    stopVoice();
    const ctx = resumeAudioContext();

    // Check native support first for speed
    if ('speechSynthesis' in window && !existing) {
        // Simple logic: Short phrases use native, Long phrases use AI voice if available
        if (text.length < 50 || !ctx) {
            fallbackNativeTTS(text, onEnded);
            return;
        }
    }

    if (!ctx) { fallbackNativeTTS(text, onEnded); return; }

    try {
        let base64 = existing;
        if (!base64 && audioCache.has(text)) base64 = audioCache.get(text);
        else if (!base64) {
            base64 = await getShadowVoice(text, voice);
            if (base64) audioCache.set(text, base64);
        }

        if (!base64) { fallbackNativeTTS(text, onEnded); return; }

        const buffer = await decodeAudioData(decode(base64), ctx);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => { currentSource = null; onEnded?.(); };
        source.start(0);
        currentSource = source;
    } catch (e) { 
        fallbackNativeTTS(text, onEnded);
    }
};

const fallbackNativeTTS = (text: string, onEnded?: () => void) => {
    try {
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'ar-EG';
        utterance.rate = 1.0; 
        const voices = window.speechSynthesis.getVoices();
        const arabicVoice = voices.find(v => v.lang.includes('ar'));
        if (arabicVoice) utterance.voice = arabicVoice;
        utterance.onend = () => onEnded?.();
        utterance.onerror = () => onEnded?.();
        window.speechSynthesis.speak(utterance);
    } catch(e) { onEnded?.(); }
};

export const getShadowVoice = async (text: string, voice: string) => {
