// --- AUDIO CONTEXT MANAGEMENT ---
let audioCtx: AudioContext | null = null;
let currentSource: AudioBufferSourceNode | null = null;
const audioCache = new Map<string, string>();
let isRequesting = false;

// Initialize or Resume Audio Context (Must be called on user interaction)
export function resumeAudioContext() {
    if (!audioCtx) {
        const CtxClass = (window.AudioContext || (window as any).webkitAudioContext);
        if (CtxClass) {
            // 24kHz is standard for Gemini Flash Audio
            audioCtx = new CtxClass({ sampleRate: 24000 });
        }
    }

    if (audioCtx && audioCtx.state === 'suspended') {
        audioCtx.resume().catch(e => console.warn("Audio Context Resume Failed:", e));
    }
    return audioCtx;
}

