// --- THE SOUL OF THE SHADOW (SYSTEM PROMPT) ---
const generateSystemPrompt = (user: UserProfile | undefined, memory: string, rules: string, agents: AgentProfile[]) => {

    // 1. TIME ANCHOR
    const now = new Date();
    const dateString = now.toLocaleDateString('ar-EG', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    const timeString = now.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });

    // 2. THE CONSTITUTION
    const coreIdentity = `
    🔴 **Protocol: SHADOW_CORE_V1**
    أنت "الظل" (Ez-Zel). الكيان الرقمي المصري الأقوى.
    مجلس إدارة متكامل (محاسب، محامي، منفذ، مستشار) في كيان واحد.

    🕒 **Time Context:** ${dateString} | ${timeString}

    💼 **أدواتك وقدراتك:**
    1. **البحث الحي (Grounding):** متصل بالإنترنت لحظياً. لو سألتك عن سعر، خبر، أو معلومة، هات الإجابة فوراً من Google Search المدمج معك. لا تطلب من المستخدم البحث.
    2. **المنفذ:** للتطبيقات والتذكيرات.
    3. **الذاكرة:** لا تنسى تفاصيل الماستر.

    🛠️ **الشخصية واللهجة:**
    - لهجة مصرية قوية "ابن بلد" وراقية، واثقة ومختصرة (يا ريس، يا كبير، يا ماستر).
    - لا تعتذر كثيراً. نفذ الأمر بذكاء.
    - لو السؤال يحتاج بحث، ابحث فوراً واكتب الإجابة في الرد.

    📂 **Memory:**
    ${memory}

    📜 **Rules:**
    ${rules}
    `;

    const parts: any[] = [{ text: coreIdentity }];

    agents.forEach(a => {
        if (a.documents?.length) {
            parts.push({ text: `\n[Agent File: ${a.role}]:` });
            a.documents.forEach(d => parts.push({ inlineData: { mimeType: d.mimeType, data: d.data.split(',')[1] || d.data } }));
        }
    });
    return parts;
};

// --- ROBUST RETRY LOGIC ---
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const generateWithRetry = async (modelName: string, params: any, maxRetries = 1): Promise<GenerateContentResponse> => {
    let currentDelay = 1000;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
            return await ai.models.generateContent({
                ...params,
                model: modelName
            });
        } catch (error: any) {
            const isTransient = error.status === 503 || error.status === 429 || error.message?.includes('Overloaded');
            if (isTransient && attempt < maxRetries) {
                console.warn(`[Shadow Core] Retrying ${modelName}...`);
                await wait(currentDelay);
                currentDelay *= 2;
                continue;
            }
            throw error;
        }
    }
    throw new Error("Generative AI Error");
};

// --- SMART EXECUTION ---
const executeSmartRequest = async (params: any, userHistory: any[], userMessage: string): Promise<GenerateContentResponse> => {
    // CORRECT CONFIGURATION: Function Declarations AND Google Search in the same array.
    const toolsConfig = [
        { functionDeclarations: actionTools },
        { googleSearch: {} }
    ];

    try {
        return await generateWithRetry("gemini-3-flash-preview", {
            ...params,
            config: { 
                ...params.config,
                tools: toolsConfig, 
                temperature: 0.7 
            }
        }); 
    } catch (error: any) {
        console.warn("[Shadow Core] Primary Brain Busy. Trying Backup...", error.message);

        // Fallback strategy: If 3-flash fails with tools, try simpler model or separate tools
        try {
            return await generateWithRetry("gemini-flash-latest", {
                ...params,
                config: {
                    ...params.config,
                    tools: toolsConfig,
                    temperature: 0.7,
                }
            });
        } catch (finalError) {
             // Ultimate Fallback: Text only (no tools) to ensure a response
             console.error("Critical Failure, dropping tools.");
             return await generateWithRetry("gemini-flash-lite-latest", {
                 ...params,
                 config: { ...params.config, tools: [] }
             }, 0);
        }
    }
};

export const getShadowResponse = async (history: any[], message: string, extraData?: any, userProfile?: UserProfile, signal?: AbortSignal) => {
    if (isRequesting) return { text: "لحظة واحدة يا ريس..", isError: true };
    isRequesting = true;

    try {
        const [mem, rules, agents] = await Promise.all([
            shadowDB.getMemory(userProfile?.email || 'GUEST'), 
            shadowDB.getGlobalRules(), 
            shadowDB.getAllAgents()
        ]);

        const systemParts = generateSystemPrompt(userProfile, mem.map(f => f.fact).join(" | "), rules, agents);
        const userParts: any[] = [{ text: message }];
        if (extraData?.data) userParts.push({ inlineData: { data: extraData.data, mimeType: extraData.mimeType } });

        const baseParams = {
            contents: [...history.slice(-8).map(h => ({ role: h.role, parts: [{ text: h.text }] })), { role: 'user', parts: userParts }],
            config: { systemInstruction: { parts: systemParts } },
        };

        const response = await executeSmartRequest(baseParams, history, message);

        const toolActions = response.functionCalls || []; 
        const grounding = response.candidates?.[0]?.groundingMetadata;

        let finalText = response.text || "";
        if (!finalText && response.candidates?.[0]?.content?.parts) {
            finalText = response.candidates[0].content.parts
                .filter((p: any) => p.text)
                .map((p: any) => p.text)
                .join("\n");
        }

        // If tools are used but no text, generate a filler
        if (!finalText && toolActions.length > 0) {
            finalText = "تمام، جاري التنفيذ...";
        }

        const groundingLinks = grounding?.groundingChunks?.map((c: any) => ({
            title: c.web?.title || "مصدر",
            uri: c.web?.uri
        })).filter((l: any) => l.uri) || [];

        return { 
            text: finalText, 
            toolActions: toolActions,
            groundingLinks: groundingLinks,
            isError: false
        };

    } catch (e: any) {
        console.error("Gemini Critical:", e);
        // Better error messages
        let errorMsg = "الشبكة علقت ثانية.. جرب تاني.";
        if (e.message?.includes('400')) errorMsg = "في حاجة مش مظبوطة في الطلب.. حاول بصيغة تانية.";
        if (e.message?.includes('429')) errorMsg = "ضغط شغل عالي.. ثانية وراجعلك.";
        return { text: errorMsg, isError: true };
    } finally { isRequesting = false; }
};

// --- VOICE ENGINE ---
export const playShadowVoice = async (text: string, voice: string, existing?: string, onEnded?: () => void) => {
    stopVoice();
    const ctx = resumeAudioContext(); 

    // Fallback immediately if text is very short or context failed
    if (!ctx || text.length < 3) {
        fallbackNativeTTS(text, onEnded);
        return;
    }

    try {
        let base64 = existing;
        if (!base64 && audioCache.has(text)) base64 = audioCache.get(text);
        else if (!base64) {
            base64 = await getShadowVoice(text, voice);
            if (base64) audioCache.set(text, base64);
        }

        if (!base64) {
            fallbackNativeTTS(text, onEnded);
            return;
        }

        const buffer = await decodeAudioData(decode(base64), ctx);
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => { currentSource = null; onEnded?.(); };
        source.start(0);
        currentSource = source;

    } catch (e) { 
        console.error("Shadow Voice Error:", e);
        fallbackNativeTTS(text, onEnded);
    }
};

const fallbackNativeTTS = (text: string, onEnded?: () => void) => {
    try {
        if (!('speechSynthesis' in window)) { onEnded?.(); return; }
        window.speechSynthesis.cancel();

        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'ar-EG'; 
        utterance.rate = 1.0; 

        // Try to pick a decent Arabic voice if available
        const voices = window.speechSynthesis.getVoices();
        const arVoice = voices.find(v => v.lang.includes('ar'));
        if (arVoice) utterance.voice = arVoice;

        utterance.onend = () => onEnded?.();
        utterance.onerror = () => onEnded?.();

        window.speechSynthesis.speak(utterance);
    } catch(e) { 
        onEnded?.(); 
    }
};

export const getShadowVoice = async (text: string, voice: string) => {
    try {
        const res = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text }] }],
            config: { 
                responseModalities: [Modality.AUDIO], 
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice === 'female' ? 'Kore' : 'Fenrir' } } } 
            }
        });
        return res.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
    } catch (e) { return null; }
};

export const stopVoice = () => { 
    if (currentSource) { try { currentSource.stop(); } catch {} currentSource = null; } 
    if (window.speechSynthesis) window.speechSynthesis.cancel();
};

function decode(b: string) { const s = atob(b); const u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u; }
async function decodeAudioData(d: Uint8Array, c: AudioContext) { const i16 = new Int16Array(d.buffer); const b = c.createBuffer(1, i16.length, 24000); const cd = b.getChannelData(0); for (let i = 0; i < i16.length; i++) cd[i] = i16[i] / 32768.0; return b; }

