// --- API KEY EXTRACTION ---
const getApiKey = (): string => {
    try {
        // @ts-ignore
        if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.VITE_API_KEY) return import.meta.env.VITE_API_KEY;
        // @ts-ignore
        if (typeof process !== 'undefined' && process.env && process.env.VITE_API_KEY) return process.env.VITE_API_KEY;
    } catch (e) {}
    // @ts-ignore
    return process.env.API_KEY || '';
};

const apiKey = getApiKey();
const ai = new GoogleGenAI({ apiKey });

// --- AUDIO CONTEXT MANAGEMENT ---
let audioCtx: AudioContext | null = null;
let currentSource: AudioBufferSourceNode | null = null;
const audioCache = new Map<string, string>();
let isRequesting = false;

// Robust Audio Unlocker (Call this on ANY user interaction)
export function resumeAudioContext() {
    try {
        if (!audioCtx) {
            const CtxClass = (window.AudioContext || (window as any).webkitAudioContext);
            if (CtxClass) {
                audioCtx = new CtxClass({ sampleRate: 24000 });
            }
        }

        if (audioCtx && audioCtx.state === 'suspended') {
            audioCtx.resume().catch(e => console.warn("Audio Resume Warning:", e));
        }

        // Also unlock SpeechSynthesis by cancelling any pending
        if ('speechSynthesis' in window) {
            window.speechSynthesis.cancel();
        }

        return audioCtx;
    } catch (e) {
        console.error("Audio Context Fatal Error:", e);
        return null;
    }
}

// --- ROBUST NATIVE TTS ENGINE ---
export const speakNative = (text: string, onEnd?: () => void) => {
    if (!('speechSynthesis' in window)) {
        onEnd?.();
        return;
    }

    const synth = window.speechSynthesis;

    // 1. Cancel ongoing speech to prevent queue jams
    synth.cancel();

    // 2. Clean text (remove markdown asterisks, hashes, etc for cleaner speech)
    const cleanText = text.replace(/[*_#\-]/g, ' ').trim();
    if (!cleanText) { onEnd?.(); return; }

    const utter = new SpeechSynthesisUtterance(cleanText);
    utter.rate = 1.0;
    utter.pitch = 1.0;
    utter.volume = 1.0;
    utter.lang = 'ar-EG'; // Default hint

    // 3. Robust Voice Selection (Wait for voices if empty)
    const selectVoiceAndSpeak = () => {
        const voices = synth.getVoices();
        // Priority: Google Arabic -> Any Arabic -> Default
        const arVoice = voices.find(v => v.name.includes('Google') && v.lang.includes('ar')) 
                     || voices.find(v => v.lang.includes('ar'));

        if (arVoice) utter.voice = arVoice;

        utter.onend = () => { onEnd?.(); };
        utter.onerror = (e) => { console.warn("TTS Error:", e); onEnd?.(); };

        synth.speak(utter);
    };

    if (synth.getVoices().length === 0) {
        synth.onvoiceschanged = selectVoiceAndSpeak;
    } else {
        selectVoiceAndSpeak();
    }
};

