                userId: uid,
                role: 'system',
                text: `🔔 **تنبيه:** ${task.task}`,
                timestamp: Date.now()
            };
            await shadowDB.saveMessage(alarmMsg);
            setLatestSystemMessage(alarmMsg);

            // 5. Mark Done
            await shadowDB.updateTaskStatus(task.id!, { notified: true });
