// Robust Audio Unlocker with Warmup Oscillator
export function resumeAudioContext() {
    try {
        if (!audioCtx) {
            const CtxClass = (window.AudioContext || (window as any).webkitAudioContext);
            if (CtxClass) {
                audioCtx = new CtxClass({ sampleRate: 24000 });
            }
        }

        if (audioCtx) {
            if (audioCtx.state === 'suspended' || audioCtx.state === 'interrupted') {
                audioCtx.resume().catch(e => console.warn("Audio Resume Warning:", e));
            }

            // WARM UP: Play tiny silent buffer to force-wake audio thread on Mobile
            try {
                const osc = audioCtx.createOscillator();
                const gain = audioCtx.createGain();
                gain.gain.value = 0.001; // Almost silent
                osc.connect(gain);
                gain.connect(audioCtx.destination);
                osc.start(0);
                osc.stop(audioCtx.currentTime + 0.1);
            } catch(e) {}
        }

        // Also unlock SpeechSynthesis
        if ('speechSynthesis' in window) {
            if (window.speechSynthesis.paused) window.speechSynthesis.resume();
            else window.speechSynthesis.cancel();
        }

        return audioCtx;
    } catch (e) {
        console.error("Audio Context Fatal Error:", e);
        return null;
    }
}

// --- ROBUST NATIVE TTS ENGINE ---
export const speakNative = (text: string, onEnd?: () => void) => {
    if (!('speechSynthesis' in window)) {
        onEnd?.();
        return;
    }

    const synth = window.speechSynthesis;
    synth.cancel(); // Kill any previous speech

    const cleanText = text.replace(/[*_#\-]/g, ' ').trim();
    if (!cleanText) { onEnd?.(); return; }

    // Split long text to chunks if needed (Native TTS sometimes hangs on long text)
    // For now, we trust the browser, but retry if it fails.

    const utter = new SpeechSynthesisUtterance(cleanText);
    utter.rate = 1.0; 
    utter.pitch = 1.0;
    utter.volume = 1.0;
    utter.lang = 'ar-EG'; 

    const selectVoiceAndSpeak = () => {
        const voices = synth.getVoices();
        // Priority: Google Arabic -> Maged (Apple) -> Any Arabic
        const arVoice = voices.find(v => v.name.includes('Google') && v.lang.includes('ar')) 
                     || voices.find(v => v.name.includes('Maged'))
                     || voices.find(v => v.lang.includes('ar'));

        if (arVoice) utter.voice = arVoice;

        utter.onend = () => { onEnd?.(); };
        utter.onerror = (e) => { console.warn("Native TTS Error:", e); onEnd?.(); };

        // Mobile Chrome quirk: speak must be called directly
        synth.speak(utter);
    };

    if (synth.getVoices().length === 0) {
        // Fallback if voices not loaded yet (try once after delay)
        setTimeout(selectVoiceAndSpeak, 100);
    } else {
        selectVoiceAndSpeak();
    }
};

