// --- API HANDLING ---
const generateWithRetry = async (modelName: string, params: any, maxRetries = 1): Promise<GenerateContentResponse> => {
    let currentDelay = 1000;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
            return await ai.models.generateContent({ ...params, model: modelName });
        } catch (error: any) {
            if (error.status === 400 || (error.message && error.message.includes("INVALID_ARGUMENT"))) throw error;
            if (attempt < maxRetries) {
                await new Promise(r => setTimeout(r, currentDelay));
                currentDelay *= 2;
                continue;
            }
            throw error;
        }
    }
    throw new Error("Generative AI Error");
};

const executeSmartRequest = async (params: any): Promise<GenerateContentResponse> => {
    const toolsConfig = [{ functionDeclarations: actionTools }];
    try {
        return await generateWithRetry("gemini-3-flash-preview", { ...params, config: { ...params.config, tools: toolsConfig, temperature: 0.7 } }); 
    } catch (error: any) {
        try {
            return await generateWithRetry("gemini-flash-latest", { ...params, config: { ...params.config, tools: toolsConfig, temperature: 0.7 } });
        } catch (finalError) {
             return await generateWithRetry("gemini-flash-lite-latest", { ...params, config: { ...params.config, tools: [] } }, 0);
        }
    }
};

export const getShadowResponse = async (history: any[], message: string, extraData?: any, userProfile?: UserProfile, signal?: AbortSignal) => {
    if (isRequesting) return { text: "لحظة واحدة يا ريس..", isError: true };
    isRequesting = true;

    try {
        const [mem, rules, agents] = await Promise.all([shadowDB.getMemory(userProfile?.email || 'GUEST'), shadowDB.getGlobalRules(), shadowDB.getAllAgents()]);
        const systemParts = generateSystemPrompt(userProfile, mem.map(f => f.fact).join(" | "), rules, agents);

        const cleanMessage = message && message.trim() ? message : ".";
        const userParts: any[] = [{ text: cleanMessage }];
        if (extraData?.data) userParts.push({ inlineData: { data: extraData.data, mimeType: extraData.mimeType } });

        const cleanHistory = history.reduce((acc: any[], h: any) => {
            if (!h.parts || h.parts.length === 0) return acc;
            const validParts = h.parts.filter((p: any) => (typeof p.text === 'string' && p.text.trim().length > 0) || p.functionCall || p.functionResponse || p.inlineData);
            if (validParts.length > 0) acc.push({ role: h.role === 'user' ? 'user' : 'model', parts: validParts });
            return acc;
        }, []);

        const baseParams = {
            contents: [...cleanHistory.slice(-10), { role: 'user', parts: userParts }],
            config: { systemInstruction: { parts: systemParts } },
        };

        const response = await executeSmartRequest(baseParams);
        const toolActions = response.functionCalls || []; 
        let finalText = response.text || "";

        if (!finalText && response.candidates?.[0]?.content?.parts) {
            finalText = response.candidates[0].content.parts.filter((p: any) => p.text).map((p: any) => p.text).join("\n");
        }
        if (!finalText && toolActions.length > 0) finalText = "تمام، جاري التنفيذ...";

        const groundingLinks = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((c: any) => ({ title: c.web?.title || "مصدر", uri: c.web?.uri })).filter((l: any) => l.uri) || [];

        return { text: finalText || "معلش يا ريس، قول تاني؟", toolActions, groundingLinks, isError: false };

    } catch (e: any) {
        console.error("Gemini Critical:", e);
        return { text: "في حاجة مش مظبوطة.. جرب تاني.", isError: true };
    } finally { isRequesting = false; }
};

// --- UNIFIED VOICE INTERFACE (THE RACE ENGINE) ---
const timeoutPromise = (ms: number) => new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout")), ms));

export const playShadowVoice = async (text: string, voice: string, existing?: string, onEnded?: () => void) => {
    stopVoice();
    const ctx = resumeAudioContext(); 

    if (!text || text.length < 2) { onEnded?.(); return; }

    // 1. FAST TRACK: For very short confirmations, use Native immediately for snappiness.
    if (text.length < 20 && (text.includes("تمام") || text.includes("حاضر") || text.includes("عيوني"))) {
        speakNative(text, onEnded);
        return;
    }

    try {
        let base64 = existing;
        if (!base64 && audioCache.has(text)) base64 = audioCache.get(text);

        if (!base64) {
             // 2. THE RACE: API vs 4 Seconds
             // If API takes > 4s, we abandon it and speak Native to prevent awkward silence.
             try {
                 console.log("Starting Audio Race...");
                 const apiAudio = await Promise.race([
                     getShadowVoice(text, voice),
                     timeoutPromise(4000) 
                 ]) as string | null;

                 if (apiAudio) {
                     base64 = apiAudio;
                     audioCache.set(text, base64);
                 }
             } catch(err) {
                 console.warn("Audio API timed out (Race Lost), switching to Native.");
                 // Fallback to Native logic below
             }
        }

        // 3. Play the winner
        if (base64 && ctx) {
            const buffer = await decodeAudioData(decode(base64), ctx);
            const source = ctx.createBufferSource();
            source.buffer = buffer;
            source.connect(ctx.destination);
            source.onended = () => { currentSource = null; onEnded?.(); };
            source.start(0);
            currentSource = source;
        } else {
            // No API audio or Race Lost -> Native
            speakNative(text, onEnded);
        }

    } catch (e) { 
        console.error("Voice Engine Failed, final fallback:", e);
        speakNative(text, onEnded);
    }
};

export const getShadowVoice = async (text: string, voice: string) => {
    try {
        const truncatedText = text.length > 400 ? text.substring(0, 400) : text;
        const res = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: truncatedText }] }],
            config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice === 'female' ? 'Kore' : 'Fenrir' } } } }
        });
        return res.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
    } catch (e) { return null; }
};

export const stopVoice = () => { 
    if (currentSource) { try { currentSource.stop(); } catch {} currentSource = null; } 
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
};

function decode(b: string) { const s = atob(b); const u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u; }
async function decodeAudioData(d: Uint8Array, c: AudioContext) { const i16 = new Int16Array(d.buffer); const b = c.createBuffer(1, i16.length, 24000); const cd = b.getChannelData(0); for (let i = 0; i < i16.length; i++) cd[i] = i16[i] / 32768.0; return b; }

