// --- QUOTA HANDLING FALLBACK ---
const safeGenerateContent = async (primaryModel: string, params: any): Promise<GenerateContentResponse> => {
    // Strategy: Try Primary -> Fallback to Lite -> Fail Gracefully
    const models = [primaryModel];
    if (primaryModel !== 'gemini-flash-lite-latest') {
        models.push('gemini-flash-lite-latest');
    }

    let lastError: any;

    for (const model of models) {
        try {
            // Adjust params for Lite model if needed (Lite supports fewer tools usually, but we try anyway)
            // If checking quota, we might want to strip complex tools for the fallback to ensure it works
            const currentParams = { ...params, model };

            return await ai.models.generateContent(currentParams);
        } catch (e: any) {
            lastError = e;
            // Detect Quota (429) or Overloaded (503)
            const isResourceExhausted = e.status === 429 || (e.message && e.message.includes('429'));
            const isServiceUnavailable = e.status === 503;

            if (isResourceExhausted || isServiceUnavailable) {
                console.warn(`[Gemini] Model ${model} exhausted/busy. Switching fallback...`);
                continue; // Try next model
            }
            throw e; // Throw immediately for other errors (400 Bad Request, etc)
        }
    }

    throw lastError;
};

// --- SMART EXECUTION ---
export const getShadowResponse = async (history: any[], message: string, extraData?: any, userProfile?: UserProfile, signal?: AbortSignal) => {
    if (isRequesting) return { text: "ثواني بجمع المعلومات...", isError: true };
    isRequesting = true;

    try {
        const [mem, rules, agents] = await Promise.all([shadowDB.getMemory(userProfile?.email || 'GUEST'), shadowDB.getGlobalRules(), shadowDB.getAllAgents()]);
        const systemInstruction = generateSystemPrompt(userProfile, mem.map(f => f.fact).join(" | "), rules, agents);

        // --- 1. INTENT ROUTING ---
        const lowerMsg = message.toLowerCase();
        const searchKeywords = ['بحث', 'سعر', 'اخبار', 'أخبار', 'طقس', 'مين هو', 'من هو', 'تاريخ', 'متى', 'كام', 'بكام', 'search', 'price', 'news', 'weather', 'who is'];
        const isSearchIntent = searchKeywords.some(kw => lowerMsg.includes(kw));

        // --- 2. IDENTITY INJECTION ---
        const now = new Date();
        const timeStamp = now.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });

        const identityInjection = `
        \n\n[SYSTEM_HIDDEN_CONTEXT]:
        - CURRENT_TIME: ${timeStamp}
        - YOUR_IDENTITY: Ez-Zel (الظل). Egyptian AI Assistant.
        - USER_NAME: ${userProfile?.name || 'Master'}.
        - INSTRUCTION: Reply in Egyptian Arabic. Be helpful, sharp, and loyal.
        `;

        const finalUserMessage = message + identityInjection;

        // --- 3. CONSTRUCT REQUEST ---
        const userParts: any[] = [{ text: finalUserMessage }];
        if (extraData?.data) userParts.push({ inlineData: { data: extraData.data, mimeType: extraData.mimeType } });

        const cleanHistory = history.reduce((acc: any[], h: any) => {
            if (!h.parts || h.parts.length === 0) return acc;
            const validParts = h.parts.filter((p: any) => (typeof p.text === 'string' && p.text.trim().length > 0) || p.functionCall || p.functionResponse || p.inlineData);
            if (validParts.length > 0) acc.push({ role: h.role === 'user' ? 'user' : 'model', parts: validParts });
            return acc;
        }, []);

        let tools: any[] = [];
        if (isSearchIntent) {
            tools = [{ googleSearch: {} }]; 
        } else {
            tools = [{ functionDeclarations: actionTools }]; 
        }

        const primaryModel = isSearchIntent ? "gemini-2.5-flash-latest" : "gemini-3-flash-preview";

        // USE SAFE GENERATE WITH FALLBACK
        const response = await safeGenerateContent(primaryModel, {
            contents: [...cleanHistory.slice(-6), { role: 'user', parts: userParts }],
            config: {
                systemInstruction: { parts: [{ text: systemInstruction }] },
                tools: tools,
                temperature: 0.7
            }
        });

        const toolActions = response.functionCalls || [];

        // EXTRACT TEXT
        let finalText = response.text || "";
        if (!finalText && response.candidates?.[0]?.content?.parts) {
            finalText = response.candidates[0].content.parts.filter((p: any) => p.text).map((p: any) => p.text).join("\n");
        }

        // HANDLE SEARCH RESULTS (GROUNDING)
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
        const groundingLinks = groundingChunks.map((c: any) => ({ title: c.web?.title || "مصدر", uri: c.web?.uri })).filter((l: any) => l.uri) || [];

        if (!finalText && toolActions.length > 0) {
            finalText = "تمام يا ريس، جاري التنفيذ.";
        } else if (!finalText && groundingLinks.length > 0) {
            finalText = "جمعتلك المعلومات من المصادر دي، بص عليها.";
        }

        return { 
            text: finalText || "معلش يا ريس، الشبكة قطعت فجأة. قول تاني؟", 
            toolActions, 
            groundingLinks, 
            isError: false 
        };

    } catch (e: any) {
        console.error("Gemini Error:", e);
        if (e.status === 429 || (e.message && e.message.includes('429'))) {
             return { text: "الضغط عالي جداً دلوقتي يا ريس. دقيقة وجرب تاني.", isError: true };
        }
        return { text: "الشبكة فيها مشكلة بسيطة.. جرب تاني.", isError: true };
    } finally { isRequesting = false; }
};

// --- UNIFIED VOICE INTERFACE (RACE + FORCE) ---
const timeoutPromise = (ms: number) => new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout")), ms));

export const playShadowVoice = async (text: string, voice: string, existing?: string, onEnded?: () => void) => {
    stopVoice();
    const ctx = resumeAudioContext(); 

    if (!text || text.length < 2) { onEnded?.(); return; }

    if (text.length < 30) {
        speakNative(text, onEnded);
        return;
    }

    try {
        let base64 = existing;
        if (!base64 && audioCache.has(text)) base64 = audioCache.get(text);

        if (!base64) {
             try {
                 const apiAudio = await Promise.race([
                     getShadowVoice(text, voice),
                     timeoutPromise(3500) 
                 ]) as string | null;

                 if (apiAudio) {
                     base64 = apiAudio;
                     audioCache.set(text, base64);
                 }
             } catch(err) {
                 console.warn("TTS API too slow, forcing native.");
             }
        }

        if (base64 && ctx) {
            const buffer = await decodeAudioData(decode(base64), ctx);
            const source = ctx.createBufferSource();
            source.buffer = buffer;
            source.connect(ctx.destination);
            source.onended = () => { currentSource = null; onEnded?.(); };
            source.start(0);
            currentSource = source;
        } else {
            speakNative(text, onEnded);
        }

    } catch (e) { 
        speakNative(text, onEnded);
    }
};

export const getShadowVoice = async (text: string, voice: string) => {
    try {
        const truncatedText = text.length > 400 ? text.substring(0, 400) : text;
        const res = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: truncatedText }] }],
            config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice === 'female' ? 'Kore' : 'Fenrir' } } } }
        });
        return res.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
    } catch (e) { return null; }
};

export const stopVoice = () => { 
    if (currentSource) { try { currentSource.stop(); } catch {} currentSource = null; } 
    if ('speechSynthesis' in window) window.speechSynthesis.cancel();
};

function decode(b: string) { const s = atob(b); const u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return u; }
async function decodeAudioData(d: Uint8Array, c: AudioContext) { const i16 = new Int16Array(d.buffer); const b = c.createBuffer(1, i16.length, 24000); const cd = b.getChannelData(0); for (let i = 0; i < i16.length; i++) cd[i] = i16[i] / 32768.0; return b; }

