            // Add slight delay between retries to backoff
            if (lastError) await new Promise(r => setTimeout(r, 1000));

            return await ai.models.generateContent({ ...params, model });
        } catch (e: any) {
            lastError = e;
            const isQuota = e.status === 429 || (e.message && e.message.includes('429'));
            const isBusy = e.status === 503;

            if (isQuota || isBusy) {
                console.warn(`[Gemini] Model ${model} exhausted. Switching to next...`);
                continue; // Try next model in the list
            }
            // If it's a client error (400), sometimes it's due to tool mismatch in newer models, try fallback anyway
            console.warn(`[Gemini] Model ${model} error: ${e.message}. Switching...`);
            continue;
        }
    }

    throw lastError; // All models failed
};

