export const speakNative = (text: string, onEnd?: () => void) => {
    if (!('speechSynthesis' in window)) { onEnd?.(); return; }

    // Cancel any ongoing speech immediately
    window.speechSynthesis.cancel();

    const cleanText = text.replace(/[*_#\-]/g, ' ').replace(/http\S+/g, '').trim();
    if (!cleanText || cleanText.length < 2) { onEnd?.(); return; }

    const utter = new SpeechSynthesisUtterance(cleanText);
    utter.rate = 1.0; // Normal speed for clarity
    utter.pitch = 1.0;
    utter.lang = 'ar-EG'; 
    utter.volume = 1.0;

    // Try to find a good Arabic voice
    const voices = window.speechSynthesis.getVoices();
    const arVoice = voices.find(v => v.lang.includes('ar'));
    if (arVoice) utter.voice = arVoice;

    utter.onend = () => { onEnd?.(); };
    utter.onerror = (e) => { console.warn("TTS Error", e); onEnd?.(); };

    // Small delay to ensure browser is ready
    setTimeout(() => {
        window.speechSynthesis.speak(utter);
    }, 10);
};

