    // 1. Hard Reset
    window.speechSynthesis.cancel();
    resumeAudioContext();

    const cleanText = text.replace(/[*_#\-]/g, ' ').replace(/http\S+/g, '').trim();
    if (!cleanText || cleanText.length < 2) { onEnd?.(); return; }

    const utter = new SpeechSynthesisUtterance(cleanText);

    // 2. Prevent Garbage Collection by assigning to window
    // @ts-ignore
    window.shadowUtterance = utter;

    utter.rate = 1.0; 
    utter.pitch = 1.0;
    utter.lang = 'ar-EG'; 
    utter.volume = 1.0;

    // 3. Robust Voice Selection
    const selectVoice = () => {
        const voices = window.speechSynthesis.getVoices();
        if (voices.length === 0) return null;

        // Try to find Google Arabic first (Most natural), then any Arabic
        const preferred = voices.find(v => v.name.includes("Google") && v.lang.includes("ar")) || 
                          voices.find(v => v.lang.includes("ar"));

        if (preferred) utter.voice = preferred;
        return preferred;
    };

    // 4. Event Handlers
    utter.onend = () => {
        // @ts-ignore
        window.shadowUtterance = null;
        onEnd?.();
    };

    utter.onerror = (e) => {
        // Ignore "interrupted" or "canceled" errors as they are often intentional
        if (e.error !== 'interrupted' && e.error !== 'canceled') {
            console.warn("TTS Error:", e);
        }
        // @ts-ignore
        window.shadowUtterance = null;
        // Don't call onEnd immediately on error to prevent UI flickering, verify state first
        if (!window.speechSynthesis.speaking) onEnd?.();
    };

    // 5. Execution Strategy
    const executeSpeak = () => {
        selectVoice();
        window.speechSynthesis.speak(utter);

        // Chrome Bug Fix: Resume indefinitely if it gets stuck
        if (cleanText.length > 100) {
            const r = setInterval(() => {
                if (!window.speechSynthesis.speaking) {
                    clearInterval(r);
                } else {
                    window.speechSynthesis.pause();
                    window.speechSynthesis.resume();
                }
            }, 14000);
        }
    };

    if (window.speechSynthesis.getVoices().length === 0) {
        window.speechSynthesis.onvoiceschanged = () => {
            executeSpeak();
            window.speechSynthesis.onvoiceschanged = null;
        };
        // Fallback safety: If onvoiceschanged doesn't fire in 500ms, speak anyway
        setTimeout(() => {
            if (!window.speechSynthesis.speaking) executeSpeak();
        }, 500);
    } else {
        // Small delay to ensure previous cancel() took effect
        setTimeout(executeSpeak, 50);
    }
};

