                        <Ear className={`w-4 h-4 ${isSentinelMode ? 'animate-pulse' : ''}`} />
                        <span className="text-[10px] font-bold hidden md:inline">{isSentinelMode ? 'الحارس نشط' : 'الحارس'}</span>
