// --- ROBUST NATIVE TTS ENGINE (PRIMARY) ---
export const speakNative = (text: string, onEnd?: () => void) => {
    if (!('speechSynthesis' in window)) { onEnd?.(); return; }

    // 1. Full Reset (Stop everything first)
    stopVoice();
    resumeAudioContext();

    const cleanText = text.replace(/[*_#\-]/g, ' ').replace(/http\S+/g, '').trim();
    if (!cleanText || cleanText.length < 2) { onEnd?.(); return; }

    const utter = new SpeechSynthesisUtterance(cleanText);

    // 2. Assign Global to prevent GC
    // @ts-ignore
    window.shadowUtterance = utter;

    utter.rate = 1.0; 
    utter.pitch = 1.0;
    utter.lang = 'ar-EG'; 
    utter.volume = 1.0;

    utter.onend = () => {
        // @ts-ignore
        window.shadowUtterance = null;
        if (resumeInterval) { clearInterval(resumeInterval); resumeInterval = null; }
        onEnd?.();
    };

    utter.onerror = (e) => {
        if (e.error !== 'interrupted' && e.error !== 'canceled') console.warn("TTS Error:", e);
        // @ts-ignore
        window.shadowUtterance = null;
        if (resumeInterval) { clearInterval(resumeInterval); resumeInterval = null; }
        // Only trigger onEnd if not intentionally cancelled
        if (e.error !== 'canceled') onEnd?.();
    };

    const executeSpeak = () => {
        const voices = window.speechSynthesis.getVoices();
        const preferred = voices.find(v => v.name.includes("Google") && v.lang.includes("ar")) || 
                          voices.find(v => v.lang.includes("ar"));
        if (preferred) utter.voice = preferred;

        window.speechSynthesis.speak(utter);

        // Chrome Long Text Fix (Global Interval)
        if (cleanText.length > 80) {
            if (resumeInterval) clearInterval(resumeInterval);
            resumeInterval = setInterval(() => {
                if (!window.speechSynthesis.speaking) {
                    clearInterval(resumeInterval);
                    resumeInterval = null;
                } else {
                    window.speechSynthesis.pause();
                    window.speechSynthesis.resume();
                }
            }, 10000); // 10s keep-alive
        }
    };

    if (window.speechSynthesis.getVoices().length === 0) {
        window.speechSynthesis.onvoiceschanged = () => {
            executeSpeak();
            window.speechSynthesis.onvoiceschanged = null;
        };
        // Fallback
        setTimeout(() => {
            if (!window.speechSynthesis.speaking) executeSpeak();
        }, 500);
    } else {
        // Immediate execution
        executeSpeak();
    }
};

