        const identityInjection = `
        \n\n[SYSTEM_HIDDEN_CONTEXT]:
        - CURRENT_TIME: ${timeStamp}
        - YOUR_IDENTITY: Ez-Zel (الظل). Egyptian AI Assistant.
        - USER_NAME: ${userProfile?.name || 'Master'}.
